51	func assertRuleFields(t *testing.T, where string, got ReportRule, want Rule, status, note string) {
52		t.Helper()
53		if got.ID != want.ID || got.Kind != want.Kind || got.Severity != want.Severity ||
54			got.Invariant != want.Invariant || got.RequiresABI != want.RequiresABI ||
55			got.Version != want.Version {
56			t.Errorf("%s definition = {id:%q kind:%q severity:%q invariant:%q requiresABI:%v version:%q}, want {id:%q kind:%q severity:%q invariant:%q requiresABI:%v version:%q}",
57				where, got.ID, got.Kind, got.Severity, got.Invariant, got.RequiresABI, got.Version,
58				want.ID, want.Kind, want.Severity, want.Invariant, want.RequiresABI, want.Version)
59		}
