163		if removed.After != nil {
164			t.Fatalf("absent new side must be null, got %+v", removed.After)
165		}
166		if removed.Before == nil {
167			t.Fatal("removed rule must keep its old side")
168		}
169		assertRuleFields(t, "removed before side", removed.Before.Rule, removedRule, StatusDefect, removedRuleEvidence)
170		assertFindingBinding(t, "removed before side", removed.Before.Finding, hash, removedRule, removedRuleEvidence)
171	
172		// --- 仍在检查的对照规则：定义一致、缺陷 -> 通过 ---
173		kept := entryByID(t, diff, keptRule.ID)
174		if kept.Change != ChangeResolvedDefect {
175			t.Fatalf("kept rule change = %q, want %q", kept.Change, ChangeResolvedDefect)
176		}
177		if kept.Before == nil || kept.After == nil {
178			t.Fatal("resolved rule must carry both sides")
179		}
180		assertRuleFields(t, "kept before side", kept.Before.Rule, keptRule, StatusDefect, "  保留规则的旧反例\n第二行  ")
181		assertRuleFields(t, "kept after side", kept.After.Rule, keptRule, StatusPass, "")
182		assertFindingBinding(t, "kept before side", kept.Before.Finding, hash, keptRule, "  保留规则的旧反例\n第二行  ")
183		if kept.After.Finding != nil {
184			t.Errorf("passing kept-rule side must carry no finding: %+v", kept.After.Finding)
185		}
186	
187		// --- 留下的规则绝不能接收到被移除规则的旧证据 ---
188		if kept.Before.Finding != nil && kept.Before.Finding.ArtifactHash != hash {
189			t.Errorf("kept finding hash = %q, want %q", kept.Before.Finding.ArtifactHash, hash)
190		}
191		if removed.Before.Finding != nil && kept.Before.Finding != nil &&
192			removed.Before.Finding.Evidence == kept.Before.Finding.Evidence {
193			t.Error("each rule must keep its own evidence; kept rule inherited the removed rule's evidence")
194		}
195	
196		// --- 汇总：移除计入一，消除计入一；不能把移除算成消除 ---
197		s := diff.Summary
198		if s.RemovedRules != 1 {
199			t.Errorf("removedRules = %d, want 1", s.RemovedRules)
200		}
201		if s.ResolvedDefects != 1 {
202			t.Errorf("resolvedDefects = %d, want 1", s.ResolvedDefects)
203		}
204		if s.NewDefects != 0 || s.StatusChanges != 0 || s.NoteChanges != 0 ||
205			s.NoChange != 0 || s.AddedRules != 0 || s.ChangedRules != 0 {
206			t.Errorf("every other count must be zero: %+v", s)
207		}
208		// 两侧缺陷总数只数各自归档中实际存在的缺陷：旧侧 2、新侧 0。
209		if s.BeforeDefects != 2 || s.AfterDefects != 0 {
210			t.Errorf("defect totals = %d/%d, want 2/0 (actual archived findings)", s.BeforeDefects, s.AfterDefects)
211		}
212	
213		// 比较是只读操作：两份归档内容与标识保持原样，证据逐字落盘（JSON 中
214		// 换行转义为 \n），中文、前后空白不被修剪。
215		for _, id := range []string{before.ReportID, after.ReportID} {
216			data, err := os.ReadFile(filepath.Join(dir, id+".json"))
217			if err != nil {
218				t.Fatal(err)
219			}
220			if !strings.Contains(string(data), `"reportId":"`+id+`"`) {
221				t.Errorf("archive %s must keep its own id", id)
222			}
223		}
224		beforeBytes, err := os.ReadFile(filepath.Join(dir, before.ReportID+".json"))
225		if err != nil {
226			t.Fatal(err)
227		}
228		wantEscaped := `"evidence":"  旧反例：该检查已被移出范围\n  reentrancy 路径第二行  "`
229		if !strings.Contains(string(beforeBytes), wantEscaped) {
230			t.Errorf("baseline archive must keep the raw evidence verbatim:\n%s", string(beforeBytes))
231		}
232	}
233	
234	// TestDiffRemovedDefectRuleAgainstEmptyNewReport 新报告没有任何规则时同样是
235	// 合法输入：旧侧这条缺陷规则仍按移除处理，新侧缺陷总数为零，不报错也不推断
236	// 为修复。
237	func TestDiffRemovedDefectRuleAgainstEmptyNewReport(t *testing.T) {
238		dir := t.TempDir()
239		artifact := sampleArtifact()
240		hash := ArtifactHash(artifact)
241	
242		removedRule := removedPairRules()[0]
243		before := saveRuleChangeCheckReport(t, dir, artifact, removedRule, StatusDefect, removedRuleEvidence)
244		// 新报告零规则：合法归档，rules 与 findings 均为空。
245		after := saveCheckReport(t, dir, artifact, nil, nil)
246	
247		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
248		if err != nil {
249			t.Fatalf("diff against a rule-less new report must succeed: %v", err)
250		}
251		if len(diff.Results) != 1 {
252			t.Fatalf("results = %d, want 1: %+v", len(diff.Results), diff.Results)
253		}
254		entry := diff.Results[0]
255		if entry.RuleID != removedRule.ID || entry.Change != ChangeRuleRemoved {
256			t.Fatalf("entry = %q/%q, want %q/%q", entry.RuleID, entry.Change, removedRule.ID, ChangeRuleRemoved)
257		}
258		if entry.After != nil {
259			t.Errorf("absent new side must be null: %+v", entry.After)
260		}
261		assertRuleFields(t, "before side", entry.Before.Rule, removedRule, StatusDefect, removedRuleEvidence)
262		assertFindingBinding(t, "before side", entry.Before.Finding, hash, removedRule, removedRuleEvidence)
263	
264		s := diff.Summary
265		if s.RemovedRules != 1 {
266			t.Errorf("removedRules = %d, want 1", s.RemovedRules)
267		}
268		if s.ResolvedDefects != 0 || s.NewDefects != 0 {
269			t.Errorf("removal must not count as a defect transition: %+v", s)
270		}
271		if s.BeforeDefects != 1 || s.AfterDefects != 0 {
272			t.Errorf("defect totals = %d/%d, want 1/0", s.BeforeDefects, s.AfterDefects)
273		}
274	}
275	
276	// TestDiffRemovedAndResolvedIndependentOfArchiveOrder 归档中的排列顺序不影响
277	// 归属：无论基准侧两条规则以何种顺序存储、新报告对照规则放在哪里，被移除
278	// 规则与已消除规则都按标识独立分类。
279	func TestDiffRemovedAndResolvedIndependentOfArchiveOrder(t *testing.T) {
280		dir := t.TempDir()
281		artifact := sampleArtifact()
282		hash := ArtifactHash(artifact)
283		rules := removedPairRules()
284		removedRule, keptRule := rules[0], rules[1]
285	
286		// 基准侧刻意把对照规则排在前面；新报告只留对照规则。
287		before := saveCheckReport(t, dir, artifact, []Rule{keptRule, removedRule}, []CheckRecord{
288			{ArtifactHash: hash, RuleID: keptRule.ID, Version: keptRule.Version, Status: StatusDefect, Note: "  保留规则的旧反例\n第二行  "},
289			{ArtifactHash: hash, RuleID: removedRule.ID, Version: removedRule.Version, Status: StatusDefect, Note: removedRuleEvidence},
290		})
291		after := saveRuleChangeCheckReport(t, dir, artifact, keptRule, StatusPass, "")
292	
293		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
294		if err != nil {
295			t.Fatal(err)
296		}
297		byID := map[string]RuleDiff{}
298		for _, r := range diff.Results {
299			byID[r.RuleID] = r
300		}
301		if byID[removedRule.ID].Change != ChangeRuleRemoved {
302			t.Errorf("removed = %q, want %q", byID[removedRule.ID].Change, ChangeRuleRemoved)
303		}
304		if byID[keptRule.ID].Change != ChangeResolvedDefect {
305			t.Errorf("kept = %q, want %q", byID[keptRule.ID].Change, ChangeResolvedDefect)
306		}
307		if s := diff.Summary; s.RemovedRules != 1 || s.ResolvedDefects != 1 ||
308			s.BeforeDefects != 2 || s.AfterDefects != 0 {
309			t.Errorf("summary = %+v, want removed=1 resolved=1 defects=2/0", s)
310		}
311	}
312	
313	// entryByID 取出指定规则标识的比较条目。
314	func entryByID(t *testing.T, diff DiffResult, ruleID string) RuleDiff {
315		t.Helper()
316		for _, r := range diff.Results {
317			if r.RuleID == ruleID {
318				return r
319			}
320		}
321		t.Fatalf("diff result for rule %s not found", ruleID)
322		return RuleDiff{}
323	}
