57		before := saveDiffReport(t, dir, artifact, beforeRules, beforeInv)
58	
59		afterRules := []Rule{
60			{ID: "added-later", Kind: "static", Severity: "low", Invariant: "inv-added", Version: "1"},
61			{ID: "changed-def", Kind: "static", Severity: "critical", Invariant: "inv-changed", Version: "1"},
62			{ID: "new-defect", Kind: "static", Severity: "high", Invariant: "inv-new", Version: "1"},
63			{ID: "resolved", Kind: "static", Severity: "medium", Invariant: "inv-resolved", Version: "1"},
64			{ID: "status-shift", Kind: "static", Severity: "low", Invariant: "inv-shift", Version: "1"},
65			{ID: "stable", Kind: "static", Severity: "medium", Invariant: "inv-stable", Version: "1"},
66			{ID: "brand-new", Kind: "static", Severity: "low", Invariant: "inv-brand", Version: "1"},
67		}
68		afterInv := map[string]bool{
69			"inv-added": true, "inv-changed": true, "inv-new": false,
70			"inv-resolved": true, "inv-shift": true, "inv-stable": true,
71			"inv-brand": true,
72		}
73		after := saveDiffReport(t, dir, artifact, afterRules, afterInv)
74	
75		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
76		if err != nil {
77			t.Fatal(err)
78		}
79		if diff.Before.ReportID != before.ReportID || diff.After.ReportID != after.ReportID {
80			t.Errorf("report refs = %+v / %+v", diff.Before, diff.After)
81		}
82		if diff.ArtifactNameChanged || diff.ArtifactHashChanged {
83			t.Error("same artifact must not be flagged as changed")
84		}
85	
86		changes := map[string]string{}
87		for _, r := range diff.Results {
88			changes[r.RuleID] = r.Change
89		}
90		want := map[string]string{
91			"added-later":   ChangeNoChange,
92			"brand-new":     ChangeRuleAdded,
93			"changed-def":   ChangeRuleChanged,
94			"new-defect":    ChangeNewDefect,
95			"removed-later": ChangeRuleRemoved,
96			"resolved":      ChangeResolvedDefect,
97			"status-shift":  ChangeStatusChanged,
98			"stable":        ChangeNoChange,
99		}
100		if len(diff.Results) != len(want) {
101			t.Fatalf("results = %d, want %d", len(diff.Results), len(want))
102		}
103		for id, w := range want {
104			if changes[id] != w {
105				t.Errorf("rule %s change = %q, want %q", id, changes[id], w)
106			}
107		}
108		// Results sorted by rule id.
109		for i := 1; i < len(diff.Results); i++ {
110			if diff.Results[i-1].RuleID >= diff.Results[i].RuleID {
111				t.Fatalf("results not sorted: %q then %q", diff.Results[i-1].RuleID, diff.Results[i].RuleID)
112			}
113		}
114		// Summary counts, including zeros.
115		s := diff.Summary
116		if s.NewDefects != 1 || s.ResolvedDefects != 1 || s.StatusChanges != 1 ||
117			s.NoChange != 2 || s.AddedRules != 1 || s.RemovedRules != 1 || s.ChangedRules != 1 {
118			t.Errorf("summary = %+v", s)
119		}
120		if s.BeforeDefects != 1 || s.AfterDefects != 1 {
121			t.Errorf("defect totals = %d/%d, want 1/1", s.BeforeDefects, s.AfterDefects)
122		}
123	}
