1	package main
2	
3	import (
4		"path/filepath"
5		"sort"
6		"strings"
7		"testing"
8	
9		"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
10	)
11	
12	// 本文件在真实命令行进程边界上回归保护“移除规则”口径：新报告缩小检查范围、
13	// 完全不再包含基准报告中某条带缺陷的规则时，diff 必须为该规则标识保留一个
14	// “移除规则”条目，旧侧仍是归档中的完整规则定义、检查状态和原始缺陷记录，新
15	// 侧为 null；这不同于同标准下复跑确认修复的“已消除缺陷”。两种变化放在同一
16	// 份比较结果中，必须各自进入对应分类与计数，不能仅凭缺陷总数下降就把移除算
17	// 成修复。两份报告都通过真实 audit 命令正常归档，再由 diff 命令读回比较，
18	// 既有报告格式、报告标识与基准/新比较方向保持兼容。
19	
20	// 被移除规则的旧证据刻意包含中文、换行与前后空格，任何修剪或模板替换都会被
21	// 抓到；它与留下规则的证据不同，防止证据按不变式名串到另一条规则上。
22	const removedRuleEvidence = "  旧反例：检查范围已收缩\n  reentrancy 路径第二行  "
23	const keptRuleEvidence = "  保留规则：旧反例\n第二行  "
24	
25	// removedCLI Rules 刻意引用同一个不变式名：归属只能按规则标识，不能按不变式。
26	func removedCLIRules() []cliWireRule {
27		return []cliWireRule{
28			{ID: "removed-reentrancy", Kind: "static", Severity: "high", Invariant: "shared-reentrancy-invariant", Version: "7.3.0"},
29			{ID: "kept-reentrancy", Kind: "static", Severity: "medium", Invariant: "shared-reentrancy-invariant", Version: "2.0.4"},
30		}
31	}
32	
33	// TestCLIDiffRemovedDefectRuleIsNotResolved 在进程边界覆盖核心口径：带缺陷
34	// 旧规则在新报告完全缺席 -> “移除规则”（新侧 null、旧证据逐字保留）；同份
35	// 输出中定义一致的对照规则缺陷 -> 通过 -> “已消除缺陷”（通过侧无缺陷记录）。
36	func TestCLIDiffRemovedDefectRuleIsNotResolved(t *testing.T) {
37		bin := auditBinary(t)
38		work := t.TempDir()
39		store := filepath.Join(work, "reports")
40		artifact := mixedCheckArtifact()
41		hash := mixedArtifactHash(t)
42		rules := removedCLIRules()
43		removedRule, keptRule := rules[0], rules[1]
44	
45		// 基准侧两条规则都为发现缺陷，各自带自己的证据；提交顺序刻意与标识排序
46		// 不同，归属不得受归档排列影响。
47		before := auditDiffReport(t, bin, work, store, "before.json", artifact,
48			[]cliWireRule{keptRule, removedRule},
49			[]cliWireCheck{
50				{ArtifactHash: hash, RuleID: keptRule.ID, Version: keptRule.Version, Status: contractsentinel.StatusDefect, Note: keptRuleEvidence},
51				{ArtifactHash: hash, RuleID: removedRule.ID, Version: removedRule.Version, Status: contractsentinel.StatusDefect, Note: removedRuleEvidence},
52			})
53		// 新报告只保留对照规则（定义完全一致）并复跑通过；被移除规则完全缺席。
54		after := auditDiffReport(t, bin, work, store, "after.json", artifact,
55			[]cliWireRule{keptRule},
56			[]cliWireCheck{
57				{ArtifactHash: hash, RuleID: keptRule.ID, Version: keptRule.Version, Status: contractsentinel.StatusPass},
58			})
59	
60		stdout, stderr, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
61		if code != 0 {
62			t.Fatalf("diff must succeed, exit=%d stderr=%s", code, stderr)
63		}
64		d := decodeDiff(t, stdout)
65	
66		// 报告标识与比较方向按命令行参数保留，两侧为同一产物。
67		if d.Before.ReportID != before.ReportID || d.After.ReportID != after.ReportID {
68			t.Errorf("refs = %q/%q, want %q/%q", d.Before.ReportID, d.After.ReportID, before.ReportID, after.ReportID)
69		}
70		if d.ArtifactNameChanged || d.ArtifactHashChanged {
71			t.Error("same artifact must not be flagged changed")
72		}
73	
74		// 每个标识恰好一个结果，共两条，按标识排序。
75		if len(d.Results) != 2 {
76			t.Fatalf("results = %d, want 2", len(d.Results))
77		}
78		ids := make([]string, 0, len(d.Results))
79		for _, r := range d.Results {
80			ids = append(ids, r.RuleID)
81		}
82		if !sort.StringsAreSorted(ids) {
83			t.Errorf("results not sorted by rule id: %v", ids)
84		}
85	
86		// --- 被移除的缺陷规则 ---
87		removed := diffEntry(t, d, removedRule.ID)
88		if removed.Change != contractsentinel.ChangeRuleRemoved {
89			t.Fatalf("removed change = %q, want %q", removed.Change, contractsentinel.ChangeRuleRemoved)
90		}
91		if removed.After != nil {
92			t.Fatalf("absent new side must be null, got %+v", removed.After)
93		}
94		if removed.Before == nil {
95			t.Fatal("removed rule must keep its old side")
96		}
97		if rb := removed.Before.Rule; rb.ID != removedRule.ID || rb.Kind != "static" ||
98			rb.Severity != "high" || rb.Invariant != "shared-reentrancy-invariant" ||
99			rb.RequiresABI != false || rb.Version != "7.3.0" {
100			t.Errorf("removed old-side rule definition = %+v, want the archived definition", rb)
101		}
102		if removed.Before.Rule.Status != contractsentinel.StatusDefect {
103			t.Errorf("removed old-side status = %q, want %q", removed.Before.Rule.Status, contractsentinel.StatusDefect)
104		}
105		if removed.Before.Rule.Note != removedRuleEvidence {
106			t.Errorf("removed old-side note = %q, want %q verbatim", removed.Before.Rule.Note, removedRuleEvidence)
107		}
108		rf := removed.Before.Finding
109		if rf == nil {
110			t.Fatal("removed old side must keep the original defect finding")
111		}
112		if rf.ArtifactHash != hash || rf.RuleID != removedRule.ID || rf.Version != removedRule.Version ||
113			rf.Severity != "high" || rf.Invariant != "shared-reentrancy-invariant" {
114			t.Errorf("removed finding binding = %+v, want hash=%q rule=%q version=%q", rf, hash, removedRule.ID, removedRule.Version)
115		}
116		if rf.Evidence != removedRuleEvidence {
117			t.Errorf("removed evidence = %q, want %q verbatim", rf.Evidence, removedRuleEvidence)
118		}
119	
120		// --- 仍在检查的对照规则：定义一致、发现缺陷 -> 通过 ---
121		kept := diffEntry(t, d, keptRule.ID)
122		if kept.Change != contractsentinel.ChangeResolvedDefect {
123			t.Fatalf("kept change = %q, want %q", kept.Change, contractsentinel.ChangeResolvedDefect)
124		}
125		if kept.Before == nil || kept.After == nil {
126			t.Fatal("resolved rule must carry both sides")
127		}
128		if kb := kept.Before.Rule; kb.ID != keptRule.ID || kb.Severity != "medium" ||
129			kb.Version != "2.0.4" || kb.Status != contractsentinel.StatusDefect ||
130			kb.Note != keptRuleEvidence {
131			t.Errorf("kept before = %+v", kb)
132		}
133		if ka := kept.After.Rule; ka.Status != contractsentinel.StatusPass || ka.Note != "" ||
134			ka.ID != keptRule.ID || ka.Version != "2.0.4" {
135			t.Errorf("kept after = %+v", ka)
136		}
137		if kept.Before.Finding == nil || kept.Before.Finding.Evidence != keptRuleEvidence ||
138			kept.Before.Finding.RuleID != keptRule.ID || kept.Before.Finding.Version != keptRule.Version ||
139			kept.Before.Finding.ArtifactHash != hash {
140			t.Errorf("kept rule must keep its own finding: %+v", kept.Before.Finding)
141		}
142		if kept.After.Finding != nil {
143			t.Errorf("passing side must carry no finding: %+v", kept.After.Finding)
144		}
145		// 留下的规则不能接收被移除规则的旧证据（两者引用同一不变式名）。
146		if kept.Before.Finding.Evidence == removedRuleEvidence {
147			t.Error("kept rule inherited the removed rule's evidence; findings must stay bound by rule id")
148		}
149	
150		// --- 汇总：两类变化各计其一，缺陷总数只数各自归档的实际发现 ---
151		s := d.Summary
