121	// 完整成功路径：同一批规则定义下所有关键迁移逐条正确归属，结果按规则 id
122	// 排序，汇总与逐条分类一致，证据逐字保留，参数位置决定基准/新报告方向。
123	func TestCLIDiffMixedTransitions(t *testing.T) {
124		bin := auditBinary(t)
125		work := t.TempDir()
126		store := filepath.Join(work, "reports")
127		artifact := mixedCheckArtifact()
128		hash := mixedArtifactHash(t)
129		rules := diffRules()
130	
131		// 两侧规则与检查记录刻意使用不同的提交排列顺序，对应关系不得受影响。
132		beforeRules := []cliWireRule{
133			rules[8], rules[3], rules[0], rules[6], rules[1], rules[7], rules[4], rules[2], rules[5],
134		}
135		afterRules := []cliWireRule{
136			rules[2], rules[7], rules[4], rules[0], rules[5], rules[8], rules[1], rules[6], rules[3],
137		}
138		before := auditDiffReport(t, bin, work, store, "before.json", artifact, beforeRules, diffBeforeChecks(hash))
139		after := auditDiffReport(t, bin, work, store, "after.json", artifact, afterRules, diffAfterChecks(hash))
140	
141		stdout, stderr, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
142		if code != 0 {
143			t.Fatalf("diff must succeed, exit=%d stderr=%s", code, stderr)
144		}
145		d := decodeDiff(t, stdout)
146	
147		// 基准与新报告的标识、产物信息必须与命令行选择一致。
148		if d.Before.ReportID != before.ReportID {
149			t.Errorf("before report id = %q, want %q", d.Before.ReportID, before.ReportID)
150		}
151		if d.After.ReportID != after.ReportID {
152			t.Errorf("after report id = %q, want %q", d.After.ReportID, after.ReportID)
153		}
154		if d.Before.Artifact.Name != "Vault" || d.Before.Artifact.Hash != hash {
155			t.Errorf("before artifact ref = %+v", d.Before.Artifact)
156		}
157		if d.After.Artifact.Name != "Vault" || d.After.Artifact.Hash != hash {
158			t.Errorf("after artifact ref = %+v", d.After.Artifact)
159		}
160		if d.ArtifactNameChanged || d.ArtifactHashChanged {
161			t.Errorf("same artifact must not be flagged changed: name=%v hash=%v", d.ArtifactNameChanged, d.ArtifactHashChanged)
162		}
163	
164		// 每条规则恰好一个结果，且两侧都在（规则集合相同）。
165		if len(d.Results) != len(rules) {
166			t.Fatalf("results = %d, want %d", len(d.Results), len(rules))
167		}
168		changeByID := map[string]string{}
169		for _, r := range d.Results {
170			changeByID[r.RuleID] = r.Change
171			if r.Before == nil || r.After == nil {
172				t.Errorf("rule %s: both sides must be present for unchanged definitions", r.RuleID)
173			}
174		}
175		wantChanges := map[string]string{
176			"a-resolved":          contractsentinel.ChangeResolvedDefect,
177			"b-tool-to-pass":      contractsentinel.ChangeStatusChanged,
178			"c-unchecked-to-pass": contractsentinel.ChangeStatusChanged,
179			"d-stable-defect":     contractsentinel.ChangeNoChange,
180			"e-stable-pass":       contractsentinel.ChangeNoChange,
181			"f-note-change":       contractsentinel.ChangeNoteChanged,
182			"m-timeout-to-defect": contractsentinel.ChangeStatusChanged,
183			"n-defect-to-timeout": contractsentinel.ChangeStatusChanged,
184			"z-new-defect":        contractsentinel.ChangeNewDefect,
185		}
186		for id, want := range wantChanges {
187			if changeByID[id] != want {
188				t.Errorf("rule %s change = %q, want %q", id, changeByID[id], want)
189			}
190		}
191	
192		// 结果必须按规则标识排序，与输入报告中的排列顺序无关。
193		ids := make([]string, 0, len(d.Results))
194		for _, r := range d.Results {
195			ids = append(ids, r.RuleID)
196		}
197		if !sort.StringsAreSorted(ids) {
198			t.Errorf("results not sorted by rule id: %v", ids)
199		}
200	
201		// 通过→发现缺陷：只有这一种迁移算新缺陷；缺陷侧携带当次归档的哈希、
202		// 规则版本与原始证据，通过侧没有缺陷记录。
203		z := diffEntry(t, d, "z-new-defect")
204		if z.Before.Rule.Status != contractsentinel.StatusPass || z.After.Rule.Status != contractsentinel.StatusDefect {
205			t.Errorf("z-new-defect statuses = %q/%q", z.Before.Rule.Status, z.After.Rule.Status)
206		}
207		if z.Before.Finding != nil {
208			t.Errorf("passing side must not carry a finding: %+v", z.Before.Finding)
209		}
210		if z.After.Finding == nil {
211			t.Fatal("defect side must carry its finding")
212		}
213		if z.After.Finding.ArtifactHash != hash || z.After.Finding.Version != "9" {
214			t.Errorf("z finding binding = %+v", z.After.Finding)
215		}
216		if z.After.Finding.Evidence != defectNote {
217			t.Errorf("z evidence = %q, want %q", z.After.Finding.Evidence, defectNote)
218		}
219	
220		// 发现缺陷→通过：已消除缺陷；证据只在基准侧。
221		a := diffEntry(t, d, "a-resolved")
222		if a.Before.Rule.Status != contractsentinel.StatusDefect || a.After.Rule.Status != contractsentinel.StatusPass {
223			t.Errorf("a-resolved statuses = %q/%q", a.Before.Rule.Status, a.After.Rule.Status)
224		}
225		if a.Before.Finding == nil || a.Before.Finding.Evidence != resolvedEvidence ||
226			a.Before.Finding.ArtifactHash != hash || a.Before.Finding.Version != "1" {
227			t.Errorf("resolved side finding = %+v", a.Before.Finding)
228		}
229		if a.After.Finding != nil {
230			t.Errorf("passing side must not carry a finding: %+v", a.After.Finding)
231		}
232	
233		// 超时→发现缺陷：只是检查状态变化，不能记为新缺陷；新侧确有缺陷记录。
234		m := diffEntry(t, d, "m-timeout-to-defect")
235		if m.Before.Rule.Status != contractsentinel.StatusTimeout || m.Before.Rule.Note != "超过 60s 截止时间" {
236			t.Errorf("m before = %+v", m.Before.Rule)
237		}
238		if m.After.Rule.Status != contractsentinel.StatusDefect || m.After.Finding == nil ||
239			m.After.Finding.Evidence != defectNote || m.After.Finding.Version != "7" || m.After.Finding.ArtifactHash != hash {
240			t.Errorf("m after must carry the real defect finding: before=%+v after=%+v", m.Before, m.After)
241		}
242		if m.Before.Finding != nil {
243			t.Errorf("timeout side must not carry a finding: %+v", m.Before.Finding)
244		}
245	
246		// 发现缺陷→超时：只是检查状态变化，不能记为已消除；旧侧缺陷记录仍在。
247		n := diffEntry(t, d, "n-defect-to-timeout")
248		if n.Before.Rule.Status != contractsentinel.StatusDefect || n.Before.Finding == nil ||
249			n.Before.Finding.Evidence != "超时前发现的反例" || n.Before.Finding.Version != "8" {
250			t.Errorf("n before must keep its defect finding: %+v", n.Before)
251		}
252		if n.After.Rule.Status != contractsentinel.StatusTimeout || n.After.Rule.Note != "复跑超过 60s 截止时间" {
253			t.Errorf("n after = %+v", n.After.Rule)
254		}
255		if n.After.Finding != nil {
256			t.Errorf("timeout side must not carry a finding: %+v", n.After.Finding)
257		}
258	
259		// 工具缺失→通过：工具缺失不证明安全，只能是状态变化；工具说明逐字保留。
260		b := diffEntry(t, d, "b-tool-to-pass")
261		if b.Before.Rule.Status != contractsentinel.StatusToolMissing || b.Before.Rule.Note != "符号执行引擎未安装" {
262			t.Errorf("b before = %+v", b.Before.Rule)
263		}
264		if b.After.Rule.Status != contractsentinel.StatusPass || b.Before.Finding != nil || b.After.Finding != nil {
265			t.Errorf("b sides = %+v / %+v", b.Before, b.After)
266		}
267	
268		// 未检查→通过：同样不能当成缺陷已消除或安全证明。
269		c := diffEntry(t, d, "c-unchecked-to-pass")
270		if c.Before.Rule.Status != contractsentinel.StatusUnchecked || c.After.Rule.Status != contractsentinel.StatusPass {
271			t.Errorf("c statuses = %q/%q", c.Before.Rule.Status, c.After.Rule.Status)
272		}
273	
274		// 无变化项：两侧状态、说明与缺陷记录一致。
275		stable := diffEntry(t, d, "d-stable-defect")
276		if stable.Before.Finding == nil || stable.After.Finding == nil ||
277			stable.Before.Finding.Evidence != "稳定缺陷证据" || stable.After.Finding.Evidence != "稳定缺陷证据" {
278			t.Errorf("stable defect sides = %+v / %+v", stable.Before.Finding, stable.After.Finding)
279		}
280		pass := diffEntry(t, d, "e-stable-pass")
281		if pass.Before.Finding != nil || pass.After.Finding != nil {
282			t.Errorf("stable pass sides must not carry findings")
283		}
284	
285		// 说明变化项各自保留自己一侧的说明。
286		note := diffEntry(t, d, "f-note-change")
287		if note.Before.Rule.Note != "旧说明" || note.After.Rule.Note != "新说明" {
288			t.Errorf("note sides = %q / %q", note.Before.Rule.Note, note.After.Rule.Note)
289		}
290	
291		// 汇总数量必须与逐条分类相符；缺陷总数只数真实缺陷，不含超时/工具缺失。
292		s := d.Summary
293		if s.NewDefects != 1 || s.ResolvedDefects != 1 || s.StatusChanges != 4 ||
294			s.NoteChanges != 1 || s.NoChange != 2 {
295			t.Errorf("summary counts = %+v", s)
296		}
297		if s.AddedRules != 0 || s.RemovedRules != 0 || s.ChangedRules != 0 {
298			t.Errorf("same rule definitions must not add/remove/change rules: %+v", s)
299		}
300		if s.BeforeDefects != 3 || s.AfterDefects != 3 {
301			t.Errorf("defect totals = %d/%d, want 3/3", s.BeforeDefects, s.AfterDefects)
302		}
303	
304		// 原始输出字节层面：证据中的中文、换行、前后空格必须逐字保留（JSON 中换行转义为 \n）。
305		if !strings.Contains(stdout, "  反例：攻击者可在 withdraw 中重入\\n  第二行证据  ") {
306			t.Errorf("diff output must preserve the raw evidence verbatim:\n%s", stdout)
307		}
308		if !strings.Contains(stdout, "  旧缺陷：重入路径仍可达\\n第二行证据  ") {
309			t.Errorf("diff output must preserve the baseline evidence verbatim:\n%s", stdout)
310		}
311	}
